begin;

insert into public.categories (name, slug, description)
values
  ('Automation agents', 'automation', 'Agents and platforms for workflows, integrations, and operations.'),
  ('Coding agents', 'coding', 'Coding, repository automation, and engineering workflows.'),
  ('Research agents', 'research', 'Agents for research, retrieval, and source-backed synthesis.'),
  ('Content agents', 'content', 'Tools for writing, documents, media, and creative workflows.')
on conflict (slug) do nothing;

with roster (
  slug, name, short_description, category_slug, tags, github_url, version_tag,
  status, stars, last_commit_at, last_release_at, requires_api_key, setup_steps,
  env_template, hardware_requirements, port_mapping, network_access, file_access,
  cost_to_run, common_errors
) as (
  values
    ('skyvern','Skyvern','Browser-workflow automation platform using LLMs and computer vision, with an SDK and workflow builder.','automation',array['browser automation','workflow builder','computer use'],'https://github.com/Skyvern-AI/skyvern','v1.0.55','published',23120,'2026-10-02T00:00:00Z','2026-10-01T00:00:00Z',true,
      jsonb_build_array('1. Install Python 3.11–3.13; if using Docker, install Docker with Compose.','2. For the Python path, run `pip install "skyvern[all]"`, then `skyvern quickstart`.','3. For Docker, copy `.env.example`, configure an LLM provider/key, and run `docker compose up -d`.','4. Open `http://localhost:8080`.'),
      'Docker quickstart requires an LLM provider and key.','Docker: 4 GB RAM minimum; 8 GB recommended','8000, 8080, 9090, 6080; browser debugging default 9222','Browser tasks can send screenshots to the configured LLM; model-provider and proxy traffic may incur separate costs','Browser workflows can upload/download files; self-hosted services mount artifacts, downloads, sessions and credential-vault storage','Self-hosted use has no per-task fee; provider/proxy costs are separate. Managed pricing not documented.','No general target allowlist or outbound-network restriction documented; do not describe as sandboxed.'),
    ('browseros','BrowserOS','Chromium-based desktop browser with an AI assistant for page questions and browser-task automation.','automation',array['AI browser','browser automation','desktop'],'https://github.com/browseros-ai/BrowserOS','0.50.5 (official updater feed; not a verified GitHub release)','published',13795,'2026-10-01T00:00:00Z',null,false,
      jsonb_build_array('1. Install the official package for your operating system; on macOS the README documents `brew install --cask browseros`.','2. Start BrowserOS and choose a built-in model, provider credentials, supported account sign-in, Ollama or LM Studio.','3. For Cowork, select a folder in its documented setup; review MCP permissions before connecting tools.'),
      'A separate API key is not required for the limited default model. BYO providers may require credentials.',NULL,'MCP endpoint 127.0.0.1:9239','MCP can control the browser, including signed-in accounts; public tunnels can expose that access','Cowork can read/write files and run shell commands; docs say the user selects a folder, but boundaries are not independently verified','Project says free; provider costs/limits may apply.','macOS minimum conflicts between quickstart (13+) and updater feed (10.15); approval policy not documented.'),
    ('decepticon','Decepticon','AI-orchestrated red-team and penetration-testing tool for authorized engagements; includes exploitation and lateral-movement workflows.','automation',array['authorized security testing','red team','Docker'],'https://github.com/BitterSecurity/Decepticon','v1.2.0 (changelog; GitHub release date unverified)','needs_review',5636,'2026-10-01T00:00:00Z',null,null,
      jsonb_build_array('1. Install Docker with Compose v2, or use a documented Podman/nerdctl alternative.','2. Install with the documented platform installer, then run `decepticon onboard`.','3. Configure a provider credential, supported subscription login or local Ollama.','4. Run `decepticon` only for a written-authorized, explicitly scoped engagement.'),
      'Provider credentials, supported subscription OAuth, or local Ollama.','Minimum 8 GB RAM and 10 GB disk; recommended 16 GB RAM and 20 GB disk','2024, 4000, 5432, 3000, 3003, 7474/7687, 8081, 9100 (not all necessarily exposed by a default run)','Engagement targets can include IP ranges, URLs and repositories; workflow includes exploitation and C2','Can use files/local paths and Docker socket','Project price not documented; provider costs may apply.','README badges and clone instructions point to PurpleAILAB/Decepticon rather than this repository; resolve canonical owner before publication.'),
    ('pentest-swarm-ai','Pentest Swarm AI','Self-hosted Go CLI that coordinates AI agents and security tools for authorized API/web testing; project describes itself as alpha.','automation',array['authorized security testing','CLI','Go'],'https://github.com/Armur-Ai/Pentest-Swarm-AI','alpha (no verified release)','published',2682,'2026-10-01T00:00:00Z',null,null,
      jsonb_build_array('1. Choose the documented npm, installer, Homebrew, Go or Docker route; npm requires Node 16+.','2. Configure a cloud model provider or a local Ollama/LM Studio model.','3. For bundled labs, install Docker.','4. Run `pentestswarm run` only against targets you are authorized to test.'),
      'Cloud LLM credentials when using a cloud provider; Ollama/LM Studio are local alternatives.',NULL,'Dashboard default localhost:7777','Performs active probes and can attempt exploits; docs describe scope checks, safe mode, spend cap and stop control','Target and scan data are handled by the CLI and configured providers; cloud-provider use means data may leave the machine','Local models avoid model API charges; cloud costs depend on provider.','README says Go 1.24 while go.mod declares Go 1.26; some capabilities are alpha/beta.'),
    ('skales','Skales','Proprietary personal AI agent for multi-step tasks, coding, browser and file work, and service integrations.','automation',array['personal assistant','desktop','mobile'],'https://github.com/skalesapp/skales','12.9.46','needs_review',1930,'2026-09-30T00:00:00Z','2026-09-30T00:00:00Z',false,
      jsonb_build_array('1. Download the official desktop or mobile installer for your platform.','2. Launch Skales; its built-in trial does not require an API key.','3. Optionally configure a BYOK provider or local Ollama.','4. Review file/browser permissions and connected-service access before use.'),
      'Built-in Skales IQ trial needs no API key; BYOK providers and cloud integrations may need their own credentials.',NULL,NULL,'Cloud-provider and connected-service workflows may send task data externally','Agent can work with files and browser; documented file/privacy boundaries are not independently verified','Private/educational use is free; commercial price not documented.','Repository is described as a distribution channel, not current application source; README/release and docs landing page show different versions. Last checked application-code commit was 2026-07-26.'),
    ('pentest-ai','Pentest AI','Python CLI and MCP/CI penetration-testing workflow with reproducibility checks and replayable findings.','automation',array['authorized security testing','CLI','MCP'],'https://github.com/0xSteph/pentest-ai','v1.4.0','published',1713,'2026-09-13T00:00:00Z','2026-09-02T00:00:00Z',null,
      jsonb_build_array('1. Install Python 3.10–3.14 and pipx.','2. Install with `pipx install ptai`.','3. For MCP use, install the AI client and run `ptai setup --mcp`.','4. Test only authorized targets; use `--no-oast` to disable documented external OAST callbacks.'),
      'Standalone cloud runs need provider credentials; local Ollama is documented. MCP uses the AI client model access.',NULL,'No default listener port documented','Blind checks may send callbacks to external OAST; no general offline guarantee','Uses supplied target and scan data','Provider costs vary. The USD 10 per-engagement default threshold is checked between calls, not a guaranteed hard cap.','Human review is recommended; a clean scan does not establish security.'),
    ('pentest-copilot','Pentest-Copilot','Self-hosted AI penetration-testing agent that runs tools on Kali or an SSH-connected host and iterates on authorized targets.','automation',array['authorized security testing','self-hosted','Kali'],'https://github.com/bugbasesecurity/pentest-copilot','No published release verified','published',1521,'2026-08-14T00:00:00Z',null,null,
      jsonb_build_array('1. Use macOS/Linux or Windows through WSL2; native Windows shells are unsupported.','2. Clone `https://github.com/bugbasesecurity/pentest-copilot.git`, enter the directory, and run `./run.sh start`.','3. Open `http://localhost:3000`, register and configure a model.','4. Configure a local workspace or SSH alias and test only authorized targets.'),
      'Choose a documented cloud provider, compatible endpoint, Codex CLI or Claude Code; credentials depend on provider.','Minimum 8 GB RAM and 20 GB disk; add 2 GB RAM for built-in Kali','3000, 8080, 6080, 9020, 27017, 6379; Kali adds 4200, 4242, 5901; Docker binds to 127.0.0.1 by default','Executes commands on configured host, can install tools and automate browser; review dangerous-command approvals','Uses configured host/SSH access, files and pentest tools','Project price not documented; model-provider costs may apply.','`./run.sh stop` stops containers but is not a full uninstall; latest code-changing commit found 2026-08-14.'),
    ('dark-moon','Dark-Moon','Autonomous penetration-testing CLI coordinating AI agents and offensive tools; findings are agent-asserted, not independently machine-verified.','automation',array['authorized security testing','CLI','Docker'],'https://github.com/ASCIT31/Dark-Moon','v1.5.0 (tag; release date not verified)','published',987,'2026-09-30T00:00:00Z',null,null,
      jsonb_build_array('1. Install Docker and Compose v2.','2. Clone `https://github.com/ASCIT31/Dark-Moon.git`, enter the directory, and run `./install.sh`.','3. Configure a cloud LLM key or local model.','4. Run `./darkmoon.sh "TARGET: example.com"` only for an authorized target.'),
      'Cloud LLM key or supported local Ollama/llama.cpp model.',NULL,'Compose mentions 9222, model endpoints 11434/8080','Actively tests targets; prompt data is sent to configured model; Compose grants host networking and Docker socket access','Compose includes read-only kube config and writable settings/reports/sessions; no enforceable target allowlist found','Darkmoon Pro is paid; price not documented; model charges may apply.','Do not treat the agent-reported exploit status as machine-verified; inspect Compose privileges before use.'),
    ('surf','Surf','Next.js application for interacting with an E2B-hosted virtual desktop; a remote-desktop demo, not a general agent SDK.','automation',array['computer use','remote desktop','demo'],'https://github.com/e2b-dev/surf','No GitHub release found','published',869,'2026-09-09T00:00:00Z',null,true,
      jsonb_build_array('1. Install Node.js and npm, then clone `https://github.com/e2b-dev/surf.git`.','2. Run `npm install`.','3. Create `.env.local` with `E2B_API_KEY` and `OPENAI_API_KEY`.','4. Run `npm run dev` and open `http://localhost:3000`.'),
      'Requires E2B_API_KEY and OPENAI_API_KEY; current source selects gpt-5.4.',NULL,'Development UI 3000','Uses E2B-hosted desktop and sends screenshots to OpenAI','Sandbox contains browser, terminal and file manager','Pricing not documented; E2B/OpenAI provider costs may apply.','Repository is a demo/app; package.json 1.0.0 is private package metadata, not a published release; latest app-code change found 2026-07-10.'),

    ('opencode','OpenCode','Open-source coding agent that inspects repositories, edits files and uses shell/tools iteratively.','coding',array['coding agent','CLI','IDE'],'https://github.com/anomalyco/opencode','v1.18.34','published',211386,'2026-09-30T00:00:00Z','2026-09-30T00:00:00Z',null,
      jsonb_build_array('1. Install with a documented package manager for your OS.','2. Run `opencode` and configure a model provider.','3. Use `opencode serve` only on a trusted local interface unless server authentication is configured.'),
      'Configure a model provider; provider credentials depend on choice.',NULL,'`opencode serve` defaults to 127.0.0.1:4096','Model requests go to configured provider; server exposure requires authentication','Build agent has broad access; plan agent is read-only','Model-provider costs vary.','Desktop app is marked beta; uninstall steps not documented.'),
    ('claude-code','Claude Code','Terminal-based coding agent for repository tasks and Git workflows.','coding',array['coding agent','CLI','terminal'],'https://github.com/anthropics/claude-code','v2.1.287','published',148908,'2026-10-01T00:00:00Z','2026-10-01T00:00:00Z',null,
      jsonb_build_array('1. Install with the official macOS/Linux/WSL installer or Windows PowerShell installer.','2. Run `claude` and sign in with an eligible Claude subscription, Console or supported cloud provider.','3. Review permissions and configure sandboxing before granting repository access.','4. Use the official uninstall instructions when removing it.'),
      'Sign-in is through an eligible Claude plan, Console or supported cloud provider; API key not required for every path.','4 GB+ RAM; x64/ARM64. macOS 13+, Windows 10 1809+/Server 2019+, Ubuntu 20.04+, Debian 10+, Alpine 3.19+','Not applicable for terminal workflow','Requires internet and model service','Reads/edits project files; permissions/sandboxing documented; Native Windows does not support sandboxing; WSL2 does','Plan/provider costs vary.','Node 22+ is needed only for the npm install route; native install does not require Node.'),
    ('codex','Codex','OpenAI terminal coding agent for software engineering tasks.','coding',array['coding agent','CLI','terminal'],'https://github.com/openai/codex','rust-v0.160.0','published',127574,'2026-10-02T00:00:00Z','2026-10-01T00:00:00Z',null,
      jsonb_build_array('1. Install with the standalone installer, npm or Homebrew.','2. Run `codex` and sign in with an eligible ChatGPT plan or API key.','3. Review the documented sandbox configuration before allowing repository changes.'),
      'Eligible ChatGPT plan or API key.','4 GB RAM minimum; 8 GB recommended. macOS 12+, Ubuntu 20.04+/Debian 10+; Windows 11 via WSL2','Not applicable for CLI','Model requests require OpenAI access','Operates on repository files; exact default security boundaries not fully documented in the cited repository pages','Plan/API costs vary.','Codex CLI is distinct from OpenAI cloud Codex; uninstall steps not documented.'),
    ('pi','Pi','Coding agent for terminal-based software tasks, with provider credentials and local GGUF model support.','coding',array['coding agent','CLI','local models'],'https://github.com/earendil-works/pi','v1.0.0','published',111458,'2026-10-02T00:00:00Z','2026-10-01T00:00:00Z',null,
      jsonb_build_array('1. Install with the documented npm route on macOS/Linux or follow the separate Windows guide.','2. For npm, use Node.js 22.19 or later.','3. Configure a provider credential or local GGUF model, then follow the quickstart to run the coding agent.','4. Use a container/sandbox if you need stronger isolation; tools run with the launching user permissions.'),
      'Provider credentials or local GGUF model.',NULL,'Not applicable for CLI','Provider network access depends on chosen model; local model option documented','Tools run with launching user permissions; no built-in permission system','Provider costs vary.','Uninstall leaves credentials, sessions and config in `~/.pi/agent/`.'),
    ('gemini-cli','Gemini CLI','Open-source terminal agent for coding tasks, shell/file operations and tools.','coding',array['coding agent','CLI','Google Gemini'],'https://github.com/google-gemini/gemini-cli','v0.62.0','published',107219,'2026-10-02T00:00:00Z','2026-09-29T00:00:00Z',false,
      jsonb_build_array('1. Install Node.js 20+ and internet access.','2. Run `npx @google/gemini-cli` or `npm install -g @google/gemini-cli`.','3. Run `gemini` and authenticate with Google account, API key or Vertex AI.','4. Configure sandboxing before running tools over untrusted content.'),
      'Google account, API key or Vertex AI authentication; an API key is not required for every documented path.','4 GB+ RAM casual use; 16 GB+ recommended for power use; Docs list macOS 15+, Windows 11 24H2+, Ubuntu 20.04+','Not applicable for CLI','Internet required; model service depends on selected authentication','Can use shell/file tools; sandbox is a configuration choice','Free-tier quotas are advertised; exact paid provider rates are not given in project sources.','Stable release v0.62.0; main branch package may identify a newer nightly.'),
    ('openhands','OpenHands','Autonomous software-development agent; current README also leads with the beta Agent Canvas self-hosted control center.','coding',array['coding agent','software engineering','self-hosted'],'https://github.com/OpenHands/OpenHands','v1.24.0','needs_review',89775,'2026-10-02T00:00:00Z','2026-09-25T00:00:00Z',null,
      jsonb_build_array('1. Follow the current Agent Canvas quickstart with Node.js 24+ and `uv`, or the documented Docker route.','2. Configure a model provider/API key.','3. Open the documented local service on port 8000.','4. Review sandbox/self-hosting guidance before granting an agent filesystem or command access.'),
      'Configure a model provider and its credentials.','Example single-user VM: Ubuntu 24.04, 2 vCPU and 4 GB RAM; not a universal minimum','Quickstart local port 8000','Model provider receives prompts/task data; external hosting may add network paths','Unsandboxed agents have broad filesystem access; sandbox/self-hosting guidance is required','Model/hosting costs vary.','Requested All-Hands-AI/OpenHands identity is stale; audited current canonical repository is OpenHands/OpenHands. Agent Canvas is beta.'),
    ('cline','Cline','User-facing coding agent with file operations, terminal and browser tools, and iterative approval loops.','coding',array['coding agent','IDE','CLI'],'https://github.com/cline/cline','Desktop v0.0.41; CLI v3.0.68','published',69698,'2026-10-02T00:00:00Z','2026-10-02T00:00:00Z',null,
      jsonb_build_array('1. Install the IDE/desktop client, or install the CLI with `npm i -g cline`.','2. Configure a hosted provider or local Ollama/LM Studio model.','3. Review file-edit and terminal approvals; avoid unattended auto-approval unless the environment is trusted.'),
      'Hosted model credentials or a supported local Ollama/LM Studio model.',NULL,'Not applicable for IDE/CLI workflow','Provider traffic depends on configured model','File changes and terminal actions ask for approval by default; auto-approval is available',NULL,'Desktop and CLI have separate version streams.'),
    ('openinterpreter','Open Interpreter','Terminal coding agent that interprets requests, writes/runs code and continues from results.','coding',array['coding agent','CLI','code execution'],'https://github.com/openinterpreter/openinterpreter','rust-v0.0.55','published',68484,'2026-10-01T00:00:00Z','2026-09-30T00:00:00Z',null,
      jsonb_build_array('1. Install with the documented shell installer for macOS/Linux or PowerShell for Windows; WSL is also documented.','2. Run `interpreter`.','3. Choose ChatGPT sign-in, provider API key, local Ollama or LM Studio.','4. Use documented sandboxing and review local execution permissions.'),
      'ChatGPT sign-in, API key or local Ollama/LM Studio.',NULL,'Terminal workflow has no documented port','Model traffic depends on selected provider','Can execute code and interact with local system; sandboxing is available and platform/settings determine boundaries',NULL,'Current Rust project; README points to a community-maintained fork for the older Python project.'),
    ('goose','Goose','Local AI agent that uses extensions/tools to inspect repositories, edit code and execute commands.','coding',array['coding agent','local','CLI'],'https://github.com/aaif-goose/goose','v1.52.0','published',54863,'2026-10-02T00:00:00Z','2026-09-23T00:00:00Z',null,
      jsonb_build_array('1. Install Goose using the quickstart for macOS, Linux or Windows.','2. Configure a provider using API key, supported account sign-in or local model.','3. Review extension/tool permissions before enabling MCP or other untrusted integrations.'),
      'Configure a model provider; credentials depend on provider.',NULL,'No default port for CLI documented','Provider and enabled extensions may receive task data','Runs tools on local machine; upstream warns to isolate and review actions, especially with MCP extensions','Model costs vary.','Runtime version and uninstall steps not documented in quickstart.'),
    ('aider','Aider','Terminal coding assistant that maps repositories, edits code, runs commands and integrates with Git.','coding',array['coding agent','CLI','Git'],'https://github.com/Aider-AI/aider','v0.86.0 (GitHub latest; project history also lists v0.86.1)','needs_review',49325,'2026-05-22T00:00:00Z','2025-08-09T00:00:00Z',null,
      jsonb_build_array('1. Install with the documented `aider-install` route; docs cover macOS/Linux and Windows.','2. Run `aider <files>` in the repository.','3. Configure a provider API key or local model.','4. Review the selected files sent to the model and use the documented Git undo flow as needed.'),
      'Provider API key or local model.','Python 3.8–3.13','Not applicable for CLI','Selected repository context is sent to chosen model provider','Edits repository files and may create Git commits','Model costs vary.','GitHub latest-release marker v0.86.0 conflicts with project history listing v0.86.1; release date also differs from source activity.'),
    ('codewhale','Codewhale','Coding agent with a core binary, optional execution tools and a local web interface.','coding',array['coding agent','CLI','local web'],'https://github.com/Hmbown/Codewhale','v0.10.0','published',41041,'2026-10-02T00:00:00Z','2026-09-22T00:00:00Z',true,
      jsonb_build_array('1. On Linux/macOS, run the documented installer `curl -fsSL https://codewhale.net/install.sh | sh`.','2. Configure the documented DeepSeek provider.','3. Run `codewhale` and choose a documented mode.','4. If enabling web mode, keep its loopback bind and runtime authentication.'),
      'Quickstart configures DeepSeek; provider credentials required.',NULL,'Optional web mode defaults to 127.0.0.1:7878','Provider requests leave the machine when using hosted model','Can execute shell and optional tools; approval modes and optional OS sandbox are documented; API keys are stored in plaintext files protected by file permissions','Provider costs vary.','Windows coverage is limited; package metadata and docs may differ on optional execution-tool requirements.'),
    ('oh-my-pi','Oh My Pi','Coding agent supporting shell/Python/Bun tools, provider authentication and local servers.','coding',array['coding agent','CLI','developer tools'],'https://github.com/can1357/oh-my-pi','v18.4.10','published',34051,'2026-10-02T00:00:00Z','2026-10-02T00:00:00Z',null,
      jsonb_build_array('1. Install using the documented shell installer, Bun, Nix or Windows PowerShell route.','2. For Bun, use Bun 1.3.14 or later.','3. Configure provider API key, OAuth/subscription or local server.','4. Review tool permissions; choose read-only collaboration links when appropriate.'),
      'Providers support API keys, OAuth/subscription and local servers.',NULL,'No default port documented','Provider connectivity depends on configured service','Runs shell/Python/Bun tools; collaboration links may be read-only or read-write','Provider costs vary.','Project describes itself as a fork of badlogic/pi-mono; do not conflate it with earendil-works/pi.'),
    ('qwen-code','Qwen Code','Terminal coding agent for repository tasks, supporting hosted providers and local Ollama/vLLM.','coding',array['coding agent','CLI','Qwen'],'https://github.com/QwenLM/qwen-code','v0.24.7','published',28271,'2026-10-02T00:00:00Z','2026-09-29T00:00:00Z',null,
      jsonb_build_array('1. Install using the standalone installer or `npm install -g @qwen-code/qwen-code@latest`; npm route requires Node.js 22+.','2. Run `qwen` and use `/auth` to configure the documented provider.','3. Choose Qwen, OpenAI, Anthropic, Gemini or local Ollama/vLLM.'),
      'Provider credential/API key or local model.','Node.js 22+ for npm route','Not applicable for CLI','Provider network access depends on configured service','Coding agent works with repository files','Model/API charges vary.','Uninstall procedure and default port not documented.'),
    ('crush','Crush','Terminal coding agent available as packages and binaries for multiple operating systems.','coding',array['coding agent','CLI','terminal'],'https://github.com/charmbracelet/crush','v0.97.1','published',28446,'2026-10-01T00:00:00Z','2026-09-29T00:00:00Z',null,
      jsonb_build_array('1. Install from a documented package manager or release binary for your platform.','2. Configure Charm Hyper, another provider API key or a local model.','3. Keep tool confirmations enabled unless you have reviewed the implications of skipping prompts.'),
      'Charm Hyper subscription, another provider credential or local model.',NULL,NULL,'Provider traffic depends on selected model','Prompts before tool calls by default; users can allow/deny tools or skip prompts','Charm Hyper is subscription-based; other provider costs are separate.','FSL-1.1-MIT restricts competing commercial use until its future MIT grant.'),
    ('kilocode','Kilo Code','Coding-agent extension, IDE plugin and CLI with access to a large model catalog.','coding',array['coding agent','IDE','CLI'],'https://github.com/Kilo-Org/kilocode','v7.8.3','published',27469,'2026-10-01T00:00:00Z','2026-10-01T00:00:00Z',false,
      jsonb_build_array('1. Install the VS Code extension, JetBrains plugin or `npm install -g @kilocode/cli`.','2. Create a Kilo account; README says no API key is needed to start.','3. Select a model and review autonomous-mode permissions before enabling `kilo run --auto`.'),
      'Kilo account; README says an API key is not needed to start.',NULL,'Not applicable for IDE/CLI','Model traffic goes to selected provider','Autonomous mode can auto-approve permission prompts unless rules deny actions; README recommends trusted environments only','Model use is billed at provider rates, with no markup stated in README.','Avoid `--auto` outside trusted environments.'),
    ('swe-agent','SWE-agent','Software-engineering agent that takes repository issues, uses tools, edits code and attempts a fix.','coding',array['coding agent','GitHub issues','Docker'],'https://github.com/SWE-agent/SWE-agent','v1.1.0','published',20457,'2026-07-16T00:00:00Z','2025-05-22T00:00:00Z',null,
      jsonb_build_array('1. Install Python 3.11+ and follow the documented editable source installation.','2. Configure a model API key; local OpenAI-compatible models are also documented.','3. Use Docker as the recommended execution backend.','4. Add a GitHub token only when working with private repositories.'),
      'Model provider credentials; local OpenAI-compatible model option documented. GitHub token for private repositories.','Python 3.11+','No default port documented','Model requests and repository access depend on configuration','Executes tools against supplied repositories; Docker is recommended','Model and compute costs are separate.','Latest version tag is old relative to later source activity; documented source install is preferable to assuming package availability.'),
    ('pr-agent','PR-Agent','Automated pull-request analysis, review comments, issue handling and code-improvement actions.','coding',array['code review','GitHub Action','pull requests'],'https://github.com/The-PR-Agent/pr-agent','v0.46.0','published',13228,'2026-10-02T00:00:00Z','2026-09-21T00:00:00Z',true,
      jsonb_build_array('1. Recommended: configure the documented GitHub Action.','2. Provide `GITHUB_TOKEN` and a model key such as `OPENAI_KEY`.','3. For pip installation, use Python 3.12+ as declared by current source.','4. Do not run untrusted fork PR code with `pull_request_target` elevated secrets.'),
      'GITHUB_TOKEN and model API key (for example OPENAI_KEY).','Python 3.12+ for pip route','No default listener port documented','GitHub and model provider receive PR metadata/content as configured','Reads PR changes; may post review comments and perform code-improvement actions','Model costs depend on provider.','Community-maintained legacy project; fork workflows can expose secrets if configured unsafely.'),
    ('codebuff','Codebuff','Coding-agent CLI distributed as a public mirror and npm package.','coding',array['coding agent','CLI','npm'],'https://github.com/CodebuffAI/freebuff','repo tag v1.0.679; npm freebuff 0.2.12 published 2026-10-02','needs_review',13079,'2026-10-02T00:00:00Z',null,false,
