    ('comfyui','ComfyUI','Node-based visual graph engine and API for modular image/video generation workflows.','content',array['node workflows','image generation','video generation'],'https://github.com/Comfy-Org/ComfyUI','Unversioned (README describes weekly releases)','published',135814,'2026-10-02T00:00:00Z',null,null,
      jsonb_build_array('1. Install the official desktop app for Windows/macOS or follow the manual Windows/Linux setup.','2. Install/select models compatible with your hardware.','3. Load or create a workflow graph and run it locally.','4. Review partner/API node settings; they can require accounts, keys or credits and send data externally.'),
      'Core can run offline; partner nodes may need account/credits/keys.','README cites some models at 4 GB VRAM + 8 GB RAM; supports NVIDIA, AMD, Intel, Apple Silicon and Ascend',NULL,'Core offline operation supported; API/partner nodes may send data to configured services','Reads local models/workflows and writes generated outputs','Cloud is paid; partner nodes use credits; current prices not documented.','Latest release/version not documented in retrieved audit evidence; no fabricated version supplied.'),
    ('open-generative-ai','Open Generative AI','Desktop/hosted image and video generation studio with local inference options.','content',array['media creation','image generation','video generation'],'https://github.com/Anil-matcha/Open-Generative-AI','v1.0.9','published',29534,'2026-10-01T00:00:00Z','2026-04-27T00:00:00Z',null,
      jsonb_build_array('1. Download the desktop build for macOS, Windows or Ubuntu, or use the hosted version.','2. For local inference, select a documented CPU, Metal, CUDA/Vulkan/ROCm backend and model.','3. Configure MuAPI credentials for hosted generation; local sd.cpp path does not need a key.','4. Review the README safety and installer-signing warnings before use.'),
      'Hosted generation uses MuAPI; local sd.cpp needs no key; provider credentials vary.','README recommends 16 GB RAM for Z-Image; other requirements model-dependent','Wan2GP example uses port 7860','Hosted generation uses MuAPI; local inference option documented','Uses selected media/model files','White-label from USD 49/month; model rates not documented.','README advertises no content filters/guardrails; installers may be unsigned/not notarized.'),
    ('invokeai','InvokeAI','Image generation and editing/canvas application with optional node workflows.','content',array['media creation','image generation','canvas'],'https://github.com/invoke-ai/InvokeAI','7.0.0-rc1 (alpha branch; latest published release not documented)','published',28327,'2026-10-02T00:00:00Z',null,null,
      jsonb_build_array('1. Install the official Launcher for Windows 10+, macOS 14+ or Linux (Ubuntu 20.04+ well-tested).','2. Use Python 3.11–3.12 when following the manual setup.','3. Select local models or configure API-only model providers.','4. Check model-specific VRAM/RAM requirements before downloading.'),
      'Local models and API-only models supported; exact key setup not documented in cited sources.','Examples: SD 1.5 at 4 GB VRAM/8 GB RAM; SDXL at 8 GB VRAM/16 GB RAM; Python 3.11–3.12',NULL,'API-backed prompts/media are sent to selected provider','Local model and generated media files',NULL,'7.0.0-rc1 is an alpha version bump; latest published release not verified.'),
    ('kotaemon','Kotaemon','Document question-answering/RAG UI and pipeline framework; not a visual node-workflow editor.','content',array['document RAG','knowledge assistant','Python'],'https://github.com/Cinnamon/kotaemon','Unversioned (latest release not documented)','published',25798,'2026-05-30T00:00:00Z',null,null,
      jsonb_build_array('1. Install Python 3.10+ and use the recommended Docker setup.','2. Choose the documented Linux amd64/arm64 container image.','3. Configure a hosted provider or local Ollama/llama.cpp model.','4. Open the UI on port 7860; configure GRAPHRAG_API_KEY only if using GraphRAG.'),
      'Hosted providers or local Ollama/llama.cpp; GraphRAG may require `GRAPHRAG_API_KEY`.','Python 3.10+','7860; local Ollama example uses 11434','Hosted models/processors may receive documents','Ingests and indexes user documents for RAG',NULL,'Categorized under Content document/RAG workspace, not visual-node workflows.'),
    ('node-banana','Node Banana','Visual editor for chaining AI media API calls into node-based workflows.','content',array['node workflows','media APIs','visual editor'],'https://github.com/shrimbly/node-banana','v1.10.0','published',1578,'2026-09-23T00:00:00Z','2026-09-23T00:00:00Z',null,
      jsonb_build_array('1. Install Node.js 18+ and npm.','2. Follow the README setup and configure a documented provider such as Gemini, Replicate, fal.ai, Kie.ai, WaveSpeed or OpenAI.','3. Start the frontend using the documented setup; it uses localhost:3000.','4. For local ComfyUI workflows, configure ComfyUI at the documented 127.0.0.1:8188 endpoint.'),
      'Provider keys configured in app/environment; local ComfyUI option available.','Node.js 18+','Frontend localhost:3000; local ComfyUI example 127.0.0.1:8188','Hosted providers receive generation requests','Workflow graph definitions and generated assets',NULL,'No blanket guarantee that all workflow nodes run locally.'),
    ('vibe-workflow','Vibe Workflow','Self-hostable visual image/video pipeline builder described as MuAPI-powered.','content',array['node workflows','image generation','video generation'],'https://github.com/SamurAIGPT/Vibe-Workflow','No GitHub release found','published',606,'2026-09-17T00:00:00Z',null,true,
      jsonb_build_array('1. Local setup requires Node.js 20+, npm 7+ and Python 3.10+; Docker 20+/Compose v2 is also documented.','2. Configure the required MuAPI key.','3. Start the documented frontend/backend or use Docker Compose; frontend/backend ports are 3000/8000.','4. Review data flow before sending prompts/media to MuAPI.'),
      'MuAPI key required.','Node.js 20+, npm 7+, Python 3.10+; Docker path requires Docker 20+ and Compose v2','Frontend 3000; backend 8000','README claims self-hosting/no third-party SaaS data, while requiring MuAPI; exact generation-data path unclear','Processes workflow/media files',NULL,'No GitHub release found; do not assume prompts/media stay local given required provider.'),
    ('moneyprinterturbo','MoneyPrinterTurbo','Creates short videos from a topic/keyword with scripts, footage, subtitles, voice and music; includes WebUI/API.','content',array['video creation','media automation','WebUI'],'https://github.com/harry0703/MoneyPrinterTurbo','v1.3.7','published',128014,'2026-10-02T00:00:00Z','2026-09-13T00:00:00Z',true,
      jsonb_build_array('1. Install Python 3.11+ and `uv`, or follow the documented Docker setup.','2. Configure the required online LLM, footage and video-provider keys.','3. Start WebUI on port 8501 or API on 8080 using the README deployment steps.','4. Review rights for generated material and bundled YouTube-sourced music.'),
      'Online LLM/footage/video providers require keys.','Windows 10+, macOS 11+, Linux; Python 3.11+; Minimum 4 CPU cores/4 GB RAM; GPU optional, 4+ GB VRAM recommended','WebUI 8501; API 8080','Provider integrations transmit input to external services','Processes/generated video assets','Provider costs vary; no unified service price documented.','README warns about possible copyright issues with bundled YouTube-sourced music.'),
    ('voicestudio','VoiceStudio','Local-first desktop voice creation, cloning, TTS, dubbing, transcription and audiobook application.','content',array['voice creation','speech','desktop'],'https://github.com/debpalash/VoiceStudio','v0.5.6','published',51562,'2026-10-01T00:00:00Z','2026-09-23T00:00:00Z',false,
      jsonb_build_array('1. Install the packaged desktop release or follow source build prerequisites: Node 22+, Bun, Rust/Cargo.','2. Choose local speech models or configure optional remote services.','3. Use the documented MCP/local API integrations as needed.','4. Clone voices only with permission; review model-specific terms.'),
      'Local processing available; remote services optional and may require credentials.','NVIDIA/CUDA, Apple Silicon/MPS and CPU documented','Ports 3900 and 3902','Local processing is available; optional remote services/analytics have separate data paths; analytics requires consent','Voice files and generated media are processed locally for the local workflow',NULL,'README cautions voice cloning should be done with permission; model terms may differ.'),
    ('pyvideotrans','pyVideoTrans','Video translation, subtitles, diarization, dubbing and audio/video synchronization app with GUI/CLI/optional WebUI.','content',array['video translation','subtitles','dubbing'],'https://github.com/jianchang512/pyvideotrans','v4.14','needs_review',19201,'2026-09-30T00:00:00Z','2026-09-26T00:00:00Z',null,
      jsonb_build_array('1. Use the packaged Windows app or install Python 3.10, FFmpeg and `uv` for source setup.','2. Follow the README steps for Windows/macOS/Linux; Docker WebUI is also documented.','3. Choose a local or online ASR/translation/TTS provider.','4. Check the repository license and README non-commercial statement before use.'),
      'Supports local and online ASR/translation/TTS providers; keys depend on selected API.','Python 3.10 recommended; NVIDIA packaged path documents CUDA 12.8/cuDNN 9.11','Docker WebUI 7860','Local/remote options have different data paths','Processes user-selected video/audio and subtitles',NULL,'License/commercial-use language conflicts between repository license metadata and README; needs maintainer clarification.'),
    ('videolingo','VideoLingo','Video workflow for speech recognition, subtitle segmentation/translation and optional dubbing; includes local HTTP API.','content',array['video translation','subtitles','dubbing'],'https://github.com/Huanshere/VideoLingo','v3.1.1','published',18556,'2026-09-30T00:00:00Z','2026-09-27T00:00:00Z',null,
      jsonb_build_array('1. Install with the documented Windows/macOS/Linux instructions; Windows path installs Python 3.12 and FFmpeg.','2. Configure LLM URL/key/model.','3. Start local API on port 8000 or Docker Streamlit on 8501 as documented.','4. Review transcription-provider charges and data path before processing media.'),
      'LLM URL/key/model required; default ASR uses local Qwen3-ASR/ForcedAligner.','Windows/macOS/Linux documented; Linux NVIDIA Docker docs specify CUDA 12.8.1','API 8000; Docker Streamlit 8501','MAI transcription sends audio to selected provider and may incur charges','Processes supplied media and writes subtitle/video outputs',NULL,'Cloning-consent policy not documented.'),
    ('toonflow-app','Toonflow','Creative short-drama/video platform with infinite canvas, story assets, nodes, agents, plugins and model integrations.','content',array['creative workflow','node workflows','video creation'],'https://github.com/HBAI-Ltd/Toonflow-app','v2.0.3','published',16332,'2026-10-01T00:00:00Z','2026-10-01T00:00:00Z',null,
      jsonb_build_array('1. Install the Windows/macOS desktop build or follow Ubuntu/Debian server setup.','2. Server setup requires Bun 1.3.14 and FFmpeg.','3. Configure model API keys or documented local ComfyUI/LLM options.','4. Keep the server behind an authenticated reverse proxy or SSH tunnel; its server has no separate login.'),
      'Model API keys configured in app; local ComfyUI/LLM options documented.','Server docs target Ubuntu/Debian','3000','Model requests go to configured providers; local options available','Projects/assets stored on device/server; server access must be restricted',NULL,'Server lacks separate login authentication. README macOS troubleshooting includes security-weakening steps; restore protections afterward.'),
    ('voice-pro','Voice-Pro','Gradio media app for speech recognition, translation, voice conversion/cloning and dubbing.','content',array['speech','voice cloning','dubbing'],'https://github.com/abus-aikorea/voice-pro','v4.0.0','needs_review',12969,'2026-07-13T00:00:00Z','2026-07-13T00:00:00Z',null,
      jsonb_build_array('1. Use the documented Windows 10/11 x64 path; macOS/Linux are listed but unverified.','2. Install Python 3.12 and download the documented model assets.','3. Configure network/provider access; default translation and TTS use Google endpoint and Edge-TTS.','4. Review license and pause status before deployment.'),
      'Azure keys optional; default translation/TTS use online services.','README lists NVIDIA recommended (4 GB VRAM, 8 GB preferred), 4 GB RAM, 20 GB disk; about 10 GB model download','Example UI 7870','Requires network; default translation/TTS use external services','Processes user-provided audio/video and voice assets',NULL,'README says development paused; license conflict: repository says GPL-3.0, README metadata says LGPL.'),
    ('opencreator','OpenCreator','Creator workspace with Codex-powered agent conversations, skills and tasks.','content',array['creator workspace','coding agent','desktop'],'https://github.com/krillinai/OpenCreator','Unversioned (release date not verified)','published',12553,'2026-10-01T00:00:00Z',null,null,
      jsonb_build_array('1. Install the macOS Apple Silicon/Intel or Windows x64 release.','2. For source use, install Node 22+ and pnpm 9.15, then install/configure Codex CLI.','3. Start the daemon on its documented loopback endpoint 127.0.0.1:19861.','4. Review credential and workspace data handling before connecting providers.'),
      'Codex CLI/provider credentials use local system credential storage.','Node 22+ and pnpm 9.15 for source use','127.0.0.1:19861','Task data may be sent to configured providers; local credential storage does not guarantee provider privacy','Runtime, attachments and workspaces are local per README',NULL,'No verified release date; do not infer a release from commit activity.'),
    ('youdub-webui','YouDub WebUI','Self-hostable video localization workflow with transcription, translation, voice generation/mixing and subtitles.','content',array['video localization','subtitles','dubbing'],'https://github.com/liuzhao1225/YouDub-webui','Unversioned (release date not verified)','published',5569,'2026-09-21T00:00:00Z',null,true,
      jsonb_build_array('1. Install Python 3.12, Node 20+ and FFmpeg/ffprobe on Windows/macOS/Linux/WSL2.','2. Configure the required OpenAI-compatible translation endpoint, key and model.','3. Use local Whisper and VoxCPM2 for the documented speech stages; select CPU/CUDA/MPS as available.','4. Enable the documented login/password authentication and process only content you have rights to use.'),
      'Requires OpenAI-compatible translation endpoint/key/model; local Whisper and VoxCPM2 handle other stages.','Python 3.12, Node 20+, FFmpeg/ffprobe; optional CUDA, CPU and MPS paths',NULL,'Transcripts go to configured translator; cookies may be used for YouTube download','Local SQLite/state/media documented',NULL,'README recommends YouTube cookies and cautions to process only rights-cleared content.'),
    ('smartsub','SmartSub','Desktop subtitle/transcription, translation, dubbing, voice cloning and rendering tool with AI copilot.','content',array['subtitles','speech','desktop'],'https://github.com/buxuku/SmartSub','Unversioned (release date not verified)','published',5450,'2026-09-30T00:00:00Z',null,false,
      jsonb_build_array('1. Install the Windows x64, macOS Apple Silicon/Intel or Linux x64 release.','2. Select local pipeline models; README says local workflow can work without keys.','3. Enable cloud ASR/translation/TTS only if needed and configure the selected provider.','4. Review voice-cloning consent and cloud data path before processing.'),
      'Local workflow can work without keys; optional cloud services need provider configuration.','NVIDIA, AMD/Intel and Apple Silicon acceleration; CPU fallback',NULL,'README says cloud use is opt-in; assistant text/images go to selected AI service, audio/video paths are passed to local tools','Processes media locally in local workflow','Local workflow is described as free; provider charges vary.','Voice-cloning consent safeguards not documented.'),
    ('sonitranslate','SoniTranslate','Gradio application for synchronized video translation and dubbing.','content',array['video translation','dubbing','Gradio'],'https://github.com/R3gm/SoniTranslate','0.5.0 (release dated 2024-05-18)','published',1417,'2026-08-29T00:00:00Z','2024-05-18T00:00:00Z',true,
      jsonb_build_array('1. Follow the documented Linux/Conda install with Python 3.10, CUDA 11.8/PyTorch, Git and FFmpeg.','2. Configure a Hugging Face token and accept gated Pyannote model terms.','3. Configure OpenAI key if using that optional service; start the UI on port 7860.','4. Do not expose a `--public_url` endpoint without access controls; use voice features only with consent.'),
      'Hugging Face token and acceptance of gated Pyannote model terms; OpenAI key optional.','Documented/tested setup is Linux, Python 3.10, NVIDIA CUDA 11.8/PyTorch','7860','Downloads models; optional public URL exposes the UI','Processes supplied video/audio and generated media',NULL,'Latest source activity is much newer than latest release; consent safeguards not documented.')
)
insert into public.agents as current_agent (
  name, slug, short_description, category_id, tags, github_url, version_tag,
  status, verification_score, requires_api_key, is_archived, stars,
  last_commit_at, last_release_at, setup_steps, env_template,
  hardware_requirements, port_mapping, network_access, file_access,
  cost_to_run, common_errors, os_commands, memory_location, uninstall_command,
  first_launch_prompt, last_verified_date, verified_commit_sha,
  verified_operating_systems, verified_install_command, verified_first_task,
  verification_failure_conditions, verification_notes,
  upstream_changed_since_verification, metadata_last_checked_at,
  metadata_source, metadata_is_stale, upstream_is_archived
)
select
  r.name,
  r.slug,
  r.short_description,
  c.id,
  r.tags,
  r.github_url,
  r.version_tag,
  r.status,
  0,
  r.requires_api_key,
  false,
  r.stars,
  r.last_commit_at::timestamptz,
  r.last_release_at::timestamptz,
  r.setup_steps,
  r.env_template,
  r.hardware_requirements,
  r.port_mapping,
  r.network_access,
  r.file_access,
  r.cost_to_run,
  r.common_errors,
  null,
  null,
  null,
  null,
  null,
  null,
  '{}'::text[],
  null,
  null,
  null,
  null,
  false,
  '2026-10-02T00:00:00Z'::timestamptz,
  'GitHub and upstream documentation snapshot, 2026-10-02',
  false,
  false
from roster r
join public.categories c on c.slug = r.category_slug
on conflict (slug) do update set
  name = excluded.name,
  short_description = excluded.short_description,
  category_id = excluded.category_id,
  tags = excluded.tags,
  github_url = excluded.github_url,
  version_tag = excluded.version_tag,
  status = excluded.status,
  requires_api_key = coalesce(excluded.requires_api_key, current_agent.requires_api_key),
  stars = excluded.stars,
  last_commit_at = excluded.last_commit_at,
  last_release_at = excluded.last_release_at,
  setup_steps = excluded.setup_steps,
  env_template = excluded.env_template,
  hardware_requirements = excluded.hardware_requirements,
  port_mapping = excluded.port_mapping,
  network_access = excluded.network_access,
  file_access = excluded.file_access,
  cost_to_run = excluded.cost_to_run,
  common_errors = excluded.common_errors,
  os_commands = case when current_agent.verification_score > 0
    then current_agent.os_commands else null end,
  uninstall_command = case when current_agent.verification_score > 0
    then current_agent.uninstall_command else null end,
  first_launch_prompt = case when current_agent.verification_score > 0
    then current_agent.first_launch_prompt else null end,
  metadata_last_checked_at = excluded.metadata_last_checked_at,
  metadata_source = excluded.metadata_source,
  metadata_is_stale = false,
  upstream_is_archived = false
where row(
  current_agent.name,
  current_agent.short_description,
  current_agent.category_id,
  current_agent.tags,
  current_agent.github_url,
  current_agent.version_tag,
  current_agent.status,
  current_agent.requires_api_key,
  current_agent.stars,
  current_agent.last_commit_at,
  current_agent.last_release_at,
  current_agent.setup_steps,
  current_agent.env_template,
  current_agent.hardware_requirements,
  current_agent.port_mapping,
  current_agent.network_access,
  current_agent.file_access,
  current_agent.cost_to_run,
  current_agent.common_errors,
  current_agent.os_commands,
  current_agent.uninstall_command,
  current_agent.first_launch_prompt,
  current_agent.metadata_last_checked_at,
  current_agent.metadata_source,
  current_agent.metadata_is_stale,
  current_agent.upstream_is_archived
) is distinct from row(
  excluded.name,
  excluded.short_description,
  excluded.category_id,
  excluded.tags,
  excluded.github_url,
  excluded.version_tag,
  excluded.status,
  coalesce(excluded.requires_api_key, current_agent.requires_api_key),
  excluded.stars,
  excluded.last_commit_at,
  excluded.last_release_at,
  excluded.setup_steps,
  excluded.env_template,
  excluded.hardware_requirements,
  excluded.port_mapping,
  excluded.network_access,
  excluded.file_access,
  excluded.cost_to_run,
  excluded.common_errors,
  case when current_agent.verification_score > 0
    then current_agent.os_commands else null end,
  case when current_agent.verification_score > 0
    then current_agent.uninstall_command else null end,
  case when current_agent.verification_score > 0
    then current_agent.first_launch_prompt else null end,
  excluded.metadata_last_checked_at,
  excluded.metadata_source,
  false,
  false
);
commit;
